1	// Query-string rewriting for matched routes: queryTransforms are applied
2	// after route selection and never touch path matching or joining. The
3	// rewriter works on raw fragments so unmodified parameters (including
4	// duplicates, empty values and empty fragments) keep their original bytes
5	// and relative order; only a rule's target parameter is decoded for name
6	// comparison and re-encoded when set.
7	package contractsentinel
8	
9	import "strings"
10	
11	// queryItem is one '&'-separated fragment of a query string in its current
12	// order. Empty fragments ("" between separators) are retained but never
13	// match a parameter name.
14	type queryItem struct {
15		empty bool   // an empty fragment, kept verbatim but not a parameter
16		name  string // decoded parameter name (only meaningful when !empty)
17		raw   string // original fragment text, or the encoded pair after a set
18	}
19	
20	// applyQueryTransforms parses the raw query of target (the text after the
21	// first '?') and applies the route's transforms in array order. It returns
22	// the full query suffix including a leading '?', or "" when the final
23	// result has no query string.
24	func applyQueryTransforms(transforms []*QueryTransform, target string) (string, *Failure) {
25		i := strings.IndexByte(target, '?')
26		if len(transforms) == 0 {
27			// No rules: the original query is preserved byte for byte.
28			if i < 0 {
29				return "", nil
30			}
31			return target[i:], nil
32		}
33	
34		var items []queryItem
35		present := false
36		if i >= 0 {
37			present = true
38			raw := target[i+1:]
39			// An empty query string ("?") has no fragments at all; every other
40			// empty fragment (e.g. from "?&" or "?a=1&") is retained as such.
41			if raw != "" {
42				for _, frag := range strings.Split(raw, "&") {
43					if frag == "" {
44						items = append(items, queryItem{empty: true})
45						continue
46					}
47					namePart := frag
48					if j := strings.IndexByte(frag, '='); j >= 0 {
49						namePart = frag[:j] // the first '=' splits name and value
50					}
51					name, ok := decodeQueryName(namePart)
52					if !ok {
53						// ParseRequest validates the whole target, so this is a
54						// belt-and-braces guard.
55						return "", failuref("invalid_request", "target contains an invalid percent escape")
56					}
57					items = append(items, queryItem{name: name, raw: frag})
58				}
59			}
60		}
61	
62		for _, tr := range transforms {
63			switch tr.Op {
64			case "remove":
65				present, items = applyRemove(items, present, tr.Name)
66			case "set":
67				present, items = applySet(items, present, tr.Name, tr.Value)
68			case "rename":
69				items = applyRename(items, tr.Name, tr.To)
70			}
71		}
72	
73		if !present {
74			return "", nil
75		}
76		parts := make([]string, len(items))
77		for k, it := range items {
78			parts[k] = it.raw
79		}
80		return "?" + strings.Join(parts, "&"), nil
81	}
82	
83	// applyRemove deletes every parameter whose decoded name equals name. With
84	// no hit the query is untouched; after a hit the '?' is dropped only when no
85	// parameters or empty fragments remain.
86	func applyRemove(items []queryItem, present bool, name string) (bool, []queryItem) {
87		first := -1
88		for k := range items {
89			if !items[k].empty && items[k].name == name {
90				first = k
91				break
92			}
93		}
94		if first < 0 {
95			return present, items
96		}
97		kept := items[:0]
98		for _, it := range items {
99			if it.empty || it.name != name {
100				kept = append(kept, it)
101			}
102		}
103		if len(kept) == 0 {
104			return false, kept
105		}
106		return true, kept
107	}
108	
109	// applySet merges all parameters with the decoded name into one encoded
110	// name=value pair at the first hit's position; a name that is absent is
111	// appended to the end and creates a query string when none existed.
112	func applySet(items []queryItem, present bool, name, value string) (bool, []queryItem) {
113		encoded := encodeQueryComponent(name) + "=" + encodeQueryComponent(value)
114		first := -1
115		for k := range items {
116			if !items[k].empty && items[k].name == name {
117				first = k
118				break
119			}
120		}
121		if first < 0 {
122			items = append(items, queryItem{name: name, raw: encoded})
123			return true, items
124		}
125		items[first].raw = encoded
126		kept := items[:first+1]
127		for _, it := range items[first+1:] {
128			if it.empty || it.name != name {
129				kept = append(kept, it)
130			}
131		}
132		return true, kept
133	}
134	
135	// applyRename renames in place every parameter whose decoded name equals
136	// name: its name is re-encoded as to while the '=' (if any) and the raw
137	// value bytes after it are kept verbatim. Parameters already named to,
138	// empty fragments and non-matching parameters are untouched; when nothing
139	// matches (or name and to are identical) every fragment keeps its bytes.
140	func applyRename(items []queryItem, name, to string) []queryItem {
141		if name == to {
142			// Renaming to the same name must not re-encode existing names.
143			return items
144		}
145		encodedTo := encodeQueryComponent(to)
146		for k := range items {
147			if items[k].empty || items[k].name != name {
148				continue
149			}
150			frag := items[k].raw
151			if j := strings.IndexByte(frag, '='); j >= 0 {
152				// Keep the '=' and everything after it byte for byte.
153				frag = encodedTo + frag[j:]
154			} else {
155				frag = encodedTo
156			}
157			items[k].raw = frag
158			items[k].name = to
159		}
160		return items
161	}
162	
163	// decodeQueryName percent-decodes a raw parameter name with '+' treated as a
164	// space, as application/x-www-form-urlencoded does. Matching is
165	// case-sensitive and applies no other normalization. The bool reports
166	// whether every percent escape was well-formed.
167	func decodeQueryName(s string) (string, bool) {
168		var b strings.Builder
169		for i := 0; i < len(s); i++ {
170			switch s[i] {
171			case '+':
172				b.WriteByte(' ')
173			case '%':
174				if i+2 >= len(s) || !isHex(s[i+1]) || !isHex(s[i+2]) {
175					return "", false
176				}
177				b.WriteByte(unhex(s[i+1])<<4 | unhex(s[i+2]))
178				i += 2
179			default:
180				b.WriteByte(s[i])
181			}
182		}
183		return b.String(), true
184	}
185	
186	// encodeQueryComponent renders a literal name or value as query text: ASCII
187	// letters, digits and -._~ stay as-is, every other byte (including spaces
188	// and the individual bytes of multi-byte UTF-8 sequences) becomes an
189	// uppercase percent escape.
190	func encodeQueryComponent(s string) string {
191		var b strings.Builder
192		for i := 0; i < len(s); i++ {
193			c := s[i]
194			if isUnreserved(c) {
195				b.WriteByte(c)
196			} else {
197				b.WriteByte('%')
198				b.WriteByte(hexDigit(c >> 4))
199				b.WriteByte(hexDigit(c & 0x0f))
200			}
201		}
202		return b.String()
203	}
204	
205	func isUnreserved(c byte) bool {
206		switch {
207		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
208			return true
209		}
210		switch c {
211		case '-', '.', '_', '~':
212			return true
213		}
214		return false
215	}
216	
217	func unhex(c byte) byte {
218		switch {
219		case c >= '0' && c <= '9':
220			return c - '0'
221		case c >= 'a' && c <= 'f':
222			return c - 'a' + 10
223		default:
224			return c - 'A' + 10
225		}
226	}
227	
228	func hexDigit(n byte) byte {
229		const digits = "0123456789ABCDEF"
230		return digits[n]
231	}
