1	// Offline route resolution: match a request against configured route prefixes
2	// and join the remainder onto the upstream base path without any network I/O.
3	package contractsentinel
4	
5	import (
6		"bytes"
7		"encoding/json"
8		"fmt"
9		"net/netip"
10		"net/url"
11		"sort"
12		"strings"
13	)
14	
15	// Route is one configured route: an id, accepted methods, a path prefix and
16	// the upstream URL requests on that route are forwarded to. An optional
17	// queryTransforms list rewrites the request query string after the route has
18	// been selected.
19	//
20	// QueryTransforms stays tag-less in the default (un)marshal sense: reading
21	// goes through Config.UnmarshalJSON via the routeJSON raw mirror, and writing
22	// goes through Route.MarshalJSON, so the rules round-trip instead of being
23	// silently dropped (a plain json:"-" tag only omitted them on save).
24	type Route struct {
25		ID         string
26		Methods    []string
27		PathPrefix string
28		Upstream   string
29	
30		// QueryTransforms holds the parsed rules. When it carries no rules the
31		// field is omitted on save, whether the source named no field or an
32		// explicit queryTransforms: [] — both are valid ways to write a route
33		// without rules, and ParseConfig accepts either.
34		QueryTransforms []*QueryTransform
35	
36		// queryTransformsRaw holds the undecoded queryTransforms value until
37		// Config.UnmarshalJSON validates it once the route's position in its own
38		// config is known. It is nil in every successfully parsed config.
39		queryTransformsRaw json.RawMessage
40	}
41	
42	// MarshalJSON writes routes back in the shape ParseConfig accepts: the four
43	// basic fields in their canonical order, followed by queryTransforms when the
44	// route carries rules. A route without rules — whether the source omitted the
45	// field or named queryTransforms: [] — omits it, and ParseConfig accepts
46	// either spelling; the field is never written as null. The rules' order and
47	// literal strings are preserved byte for byte apart from JSON string
48	// escaping, so re-parsing the output and resolving yields the same routeId
49	// and upstreamURL. Unexported fields never appear in the output.
50	func (r Route) MarshalJSON() ([]byte, error) {
51		type routeOut struct {
52			ID              string            `json:"id"`
53			Methods         []string          `json:"methods"`
54			PathPrefix      string            `json:"pathPrefix"`
55			Upstream        string            `json:"upstream"`
56			QueryTransforms []*QueryTransform `json:"queryTransforms,omitempty"`
57		}
58		return json.Marshal(routeOut{
59			ID:              r.ID,
60			Methods:         r.Methods,
61			PathPrefix:      r.PathPrefix,
62			Upstream:        r.Upstream,
63			QueryTransforms: r.QueryTransforms,
64		})
65	}
66	
67	// QueryTransform is one rule in a route's queryTransforms array: op is
68	// "set", "remove" or "rename"; name is matched against decoded parameter
69	// names, value (set only) is used literally, and to (rename only) is the
70	// literal replacement name.
71	type QueryTransform struct {
72		Op    string `json:"op"`
73		Name  string `json:"name"`
74		Value string `json:"value"`
75		To    string `json:"to"`
76	}
77	
78	// MarshalJSON renders each rule so the output satisfies the same constraints
79	// parseQueryTransforms enforces on input:
80	//   - set keeps "value" as a JSON string, including the empty string;
81	//   - remove emits only op and name (never value or to);
82	//   - rename keeps a non-empty "to" and never emits value.
83	//
84	// name, value and to are written as the literal strings read in — spaces,
85	// non-ASCII letters, '+' and '%' included — with only JSON string escaping,
86	// never query-string percent-encoding or decoding, so a re-read matches the
87	// same parameter names and applies the same literal values.
88	func (q *QueryTransform) MarshalJSON() ([]byte, error) {
89		switch q.Op {
90		case "set":
91			return json.Marshal(struct {
92				Op    string `json:"op"`
93				Name  string `json:"name"`
94				Value string `json:"value"`
95			}{q.Op, q.Name, q.Value})
96		case "rename":
97			return json.Marshal(struct {
98				Op   string `json:"op"`
99				Name string `json:"name"`
100				To   string `json:"to"`
101			}{q.Op, q.Name, q.To})
102		default:
103			// remove (and any op a validated config could never carry) writes
104			// neither value nor to, so the output cannot gain fields the reader
105			// rejects.
106			return json.Marshal(struct {
107				Op   string `json:"op"`
108				Name string `json:"name"`
109			}{q.Op, q.Name})
110		}
111	}
112	
113	// routeJSON mirrors Route but keeps every field raw: the basic fields are
114	// type-checked in Config.UnmarshalJSON with the route's position (and, when
115	// available, its id), so a wrong field type is reported on that route rather
116	// than as a generic JSON decode error, and queryTransforms can surface
117	// null, wrong types and malformed rules the same way.
118	type routeJSON struct {
119		ID              json.RawMessage `json:"id"`
120		Methods         json.RawMessage `json:"methods"`
121		PathPrefix      json.RawMessage `json:"pathPrefix"`
122		Upstream        json.RawMessage `json:"upstream"`
123		QueryTransforms json.RawMessage `json:"queryTransforms"`
124	}
125	
126	// decodeRoute type-checks and decodes one raw route object. loc is the
127	// route's 1-based location in its config (e.g. "route 2"). The element's JSON
128	// type is checked first: a null entry or any non-object value fails on the
129	// entry itself, naming the position, the required object type and the type
130	// actually received, instead of falling through to a missing-field error such
131	// as a missing id. Field type errors then carry that location and, when the
132	// route supplies a valid non-empty string id anywhere in its object (even
133	// after the offending field), that id. Missing fields stay silent here and
134	// are rejected later by validate, which preserves the existing missing-field
135	// behavior.
136	func decodeRoute(data []byte, loc string) (Route, *Failure) {
137		elem := bytes.TrimSpace(data)
138		if len(elem) == 0 || elem[0] != '{' {
139			return Route{}, failuref("invalid_config",
140				"%s: route entry must be an object, got %s", loc, jsonTypeName(elem))
141		}
142		var rj routeJSON
143		if err := json.Unmarshal(elem, &rj); err != nil {
144			// The element already parsed as one JSON value and starts with '{';
145			// an object that cannot be read is a syntax failure rather than a
146			// field type error.
147			return Route{}, failuref("invalid_config", "config is not valid JSON: %v", err)
148		}
149	
150		var route Route
151		// Type-check id first so it can identify the route on an error in any
152		// later field regardless of object order. Only a valid non-empty JSON
153		// string becomes the label; a wrong-typed id is reported against the id
154		// field and never rendered (e.g. as a number or object) as the route's
155		// identity, so that error is located by position alone.
156		if !decodeStringField(rj.ID, &route.ID) {
157			return Route{}, failuref("invalid_config", "%s: id must be a string", loc)
158		}
159		label := loc
160		if route.ID != "" {
161			label = routeLabel(loc, route.ID)
162		}
163	
164		if f := decodeMethodsField(rj.Methods, label, &route.Methods); f != nil {
165			return Route{}, f
166		}
167		if f := decodeRouteStringField(rj.PathPrefix, label, "pathPrefix", &route.PathPrefix); f != nil {
168			return Route{}, f
169		}
170		if f := decodeRouteStringField(rj.Upstream, label, "upstream", &route.Upstream); f != nil {
171			return Route{}, f
172		}
173		route.queryTransformsRaw = rj.QueryTransforms
174		return route, nil
175	}
176	
177	// decodeRouteStringField renders a route field's string type error with the
178	// route's position (and, when available, its id); the type decision itself is
179	// the shared decodeStringField. An absent field stays silent for the later
180	// required-field validation.
181	func decodeRouteStringField(raw json.RawMessage, label, field string, dst *string) *Failure {
182		if !decodeStringField(raw, dst) {
183			return failuref("invalid_config", "%s: %s must be a string", label, field)
184		}
185		return nil
186	}
187	
188	// decodeStringField type-checks a raw field that must hold a string. It is
189	// the one shared string-field decision used by both config and request
190	// decoding, so the absent / null / non-string / empty-string distinctions
191	// live in one place. It returns false only when the key is present with a
192	// non-string value (null included), which is always a field type error. An
193	// absent key leaves dst untouched, and a present string — the empty string
194	// included — is decoded into dst, so both reach the existing content checks
195	// unchanged.
196	func decodeStringField(raw json.RawMessage, dst *string) (isString bool) {
197		if len(raw) == 0 {
198			return true
199		}
200		return jsonString(raw, dst)
201	}
202	
203	// decodeMethodsField type-checks methods: it must be an array of strings
204	// when present. An absent field is left nil for later required-field
205	// validation; null or any non-array value fails the field, and a number,
206	// boolean, object or null entry fails with the offending entry's position.
207	func decodeMethodsField(raw json.RawMessage, label string, dst *[]string) *Failure {
208		if len(raw) == 0 {
209			return nil
210		}
211		body := bytes.TrimSpace(raw)
212		if string(body) == "null" || len(body) == 0 || body[0] != '[' {
213			return failuref("invalid_config", "%s: methods must be an array of strings", label)
214		}
215		var elems []json.RawMessage
216		if err := json.Unmarshal(body, &elems); err != nil {
217			return failuref("invalid_config", "%s: methods must be an array of strings", label)
218		}
219		methods := make([]string, 0, len(elems))
220		for i, elem := range elems {
221			var m string
222			if !jsonString(bytes.TrimSpace(elem), &m) {
223				return failuref("invalid_config", "%s: methods entry %d must be a string", label, i+1)
224			}
225			methods = append(methods, m)
226		}
227		*dst = methods
228		return nil
229	}
230	
231	// parseQueryTransforms decodes and validates the raw queryTransforms array
232	// of one route. loc identifies the route; rule errors additionally carry a
233	// 1-based rule index.
234	func parseQueryTransforms(raw json.RawMessage, loc, id string) ([]*QueryTransform, *Failure) {
235		body := strings.TrimSpace(string(raw))
236		if body == "null" {
237			return nil, failuref("invalid_config", "%s: queryTransforms must not be null", routeLabel(loc, id))
238		}
239		var elems []json.RawMessage
240		if err := json.Unmarshal([]byte(body), &elems); err != nil {
241			return nil, failuref("invalid_config", "%s: queryTransforms must be an array", routeLabel(loc, id))
242		}
243		transforms := make([]*QueryTransform, 0, len(elems))
244		for i, elem := range elems {
245			ruleLoc := fmt.Sprintf("%s, queryTransforms rule %d", routeLabel(loc, id), i+1)
246			if string(bytes.TrimSpace(elem)) == "null" {
247				return nil, failuref("invalid_config", "%s: rule must not be null", ruleLoc)
248			}
249			var fields map[string]json.RawMessage
250			if err := json.Unmarshal(elem, &fields); err != nil {
251				return nil, failuref("invalid_config", "%s: rule must be a JSON object", ruleLoc)
252			}
253	
254			qt := &QueryTransform{}
255			opRaw, ok := fields["op"]
256			switch {
257			case !ok:
258				return nil, failuref("invalid_config", "%s: op is required", ruleLoc)
259			case !jsonString(opRaw, &qt.Op):
260				return nil, failuref("invalid_config", "%s: op must be a string", ruleLoc)
261			case qt.Op != "set" && qt.Op != "remove" && qt.Op != "rename":
262				return nil, failuref("invalid_config", "%s: unknown op %q (only set, remove and rename are supported)", ruleLoc, qt.Op)
263			}
264	
265			nameRaw, ok := fields["name"]
266			switch {
267			case !ok:
268				return nil, failuref("invalid_config", "%s: name is required", ruleLoc)
269			case !jsonString(nameRaw, &qt.Name):
270				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
271			case qt.Name == "":
272				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
273			}
274	
275			valueRaw, hasValue := fields["value"]
276			toRaw, hasTo := fields["to"]
277			switch qt.Op {
278			case "set":
279				if !hasValue {
280					return nil, failuref("invalid_config", "%s: set requires a string value", ruleLoc)
281				}
282				if !jsonString(valueRaw, &qt.Value) {
283					return nil, failuref("invalid_config", "%s: value must be a string", ruleLoc)
284				}
285			case "remove":
286				if hasValue {
287					return nil, failuref("invalid_config", "%s: remove must not include a value", ruleLoc)
288				}
289			case "rename":
290				if hasValue {
291					return nil, failuref("invalid_config", "%s: rename must not include a value", ruleLoc)
292				}
293				switch {
294				case !hasTo:
295					return nil, failuref("invalid_config", "%s: rename requires a non-empty string to", ruleLoc)
296				case !jsonString(toRaw, &qt.To):
297					return nil, failuref("invalid_config", "%s: to must be a non-empty string", ruleLoc)
298				case qt.To == "":
299					return nil, failuref("invalid_config", "%s: to must be a non-empty string", ruleLoc)
300				}
301			}
302			transforms = append(transforms, qt)
303		}
304		return transforms, nil
305	}
306	
307	// jsonString decodes raw into s and reports whether raw is a JSON string
308	// (null, numbers, objects and arrays fail).
309	func jsonString(raw json.RawMessage, s *string) bool {
310		if len(raw) == 0 || raw[0] != '"' {
311			return false
312		}
313		return json.Unmarshal(raw, s) == nil
314	}
315	
316	// routeLabel renders the human-readable route location, adding the id when
317	// the configuration supplied one.
318	func routeLabel(loc, id string) string {
319		if id != "" {
320			return fmt.Sprintf("%s (id %q)", loc, id)
321		}
322		return loc
323	}
324	
325	// Config is the resolve configuration: a flat array of routes.
326	type Config struct {
327		Routes []Route `json:"routes"`
328	}
329	
330	// MarshalJSON writes the config back in the shape ParseConfig accepts. A
331	// non-nil empty (or nil) routes slice is emitted as "routes": [] rather than
332	// "routes": null, which ParseConfig would reject with invalid_config; the
333	// routes keep their parsed order and each route marshals through
334	// Route.MarshalJSON so its queryTransforms survive the save.
335	func (cfg *Config) MarshalJSON() ([]byte, error) {
336		routes := cfg.Routes
337		if routes == nil {
338			routes = []Route{}
339		}
340		return json.Marshal(struct {
341			Routes []Route `json:"routes"`
342		}{Routes: routes})
343	}
344	
345	// UnmarshalJSON first confirms the document is one syntactically valid JSON
346	// value, then checks its structure: the top-level value must be a JSON object
347	// and, when present, the routes field must hold an array. A syntactically
348	// legal value of the wrong shape (an array, string, number, boolean or null
349	// at the top level; a non-array routes, null included) is an invalid_config
350	// naming both the required type and the type received, never a JSON parse
351	// failure. The routes array is then decoded one entry at a time, each entry
352	// type-checked and validated against its 1-based position in this config; a
353	// non-object entry (null included) fails on that entry before any field is
354	// inspected. Decoding entries from raw values means wrong field types are
355	// reported on the offending route (with its id when available) instead of
356	// as a generic JSON syntax failure. The position comes from the array
357	// decoded here, so configs parsed concurrently or interleaved in the same
358	// process cannot shift each other's route numbering. A broken JSON document
359	// still fails the outer decode and is reported as a parse failure, without a
360	// guessed route position or field.
361	func (cfg *Config) UnmarshalJSON(data []byte) error {
362		// Syntax first, then the top-level shape; both basic checks are shared
363		// with ParseRequest (see unmarshalJSONValue / requireJSONObject), only
364		// the code and wording differ.
365		body, err := unmarshalJSONValue(data)
366		if err != nil {
367			return err
368		}
369		if f := requireJSONObject(body, "invalid_config", "config", true); f != nil {
370			return f
371		}
372		var fields map[string]json.RawMessage
373		if err := json.Unmarshal(body, &fields); err != nil {
374			return err
375		}
376	
377		var rawRoutes []json.RawMessage
378		if raw, ok := fields["routes"]; ok {
379			body := bytes.TrimSpace(raw)
380			if len(body) == 0 || body[0] != '[' {
381				// null is a type error here, never an absent field: a config
382				// that explicitly supplies routes must supply an array.
383				return failuref("invalid_config", "routes must be an array, got %s", jsonTypeName(body))
384			}
385			if err := json.Unmarshal(body, &rawRoutes); err != nil {
386				return err
387			}
388		}
389	
390		// Pass 1: decode and type-check every entry, so a wrong field type on a
391		// later route fails before any queryTransforms validation (matching the
392		// precedence of decoding before validation).
393		cfg.Routes = make([]Route, len(rawRoutes))
394		for i, entry := range rawRoutes {
395			route, f := decodeRoute(entry, fmt.Sprintf("route %d", i+1))
396			if f != nil {
397				return f
398			}
399			cfg.Routes[i] = route
400		}
401		// Pass 2: validate each route's queryTransforms now that every position
402		// is known.
403		for i := range cfg.Routes {
404			route := &cfg.Routes[i]
405			if len(route.queryTransformsRaw) == 0 {
406				continue // field absent
407			}
408			loc := fmt.Sprintf("route %d", i+1)
409			transforms, f := parseQueryTransforms(route.queryTransformsRaw, loc, route.ID)
410			if f != nil {
411				return f
412			}
413			route.QueryTransforms = transforms
414			route.queryTransformsRaw = nil
415		}
416		return nil
417	}
418	
419	// unmarshalJSONValue is the shared first step of parsing either input: it
420	// confirms the document is one syntactically valid JSON value, without
421	// judging its shape. It returns encoding/json's own error verbatim, so each
422	// caller keeps its existing handling (ParseConfig wraps a returned error just
423	// as Config.UnmarshalJSON returning it directly always has).
424	func unmarshalJSONValue(data []byte) (json.RawMessage, error) {
425		var doc json.RawMessage
426		if err := json.Unmarshal(data, &doc); err != nil {
427			return nil, err
428		}
429		return bytes.TrimSpace(doc), nil
430	}
431	
432	// requireJSONObject is the shared top-level shape check: a syntactically
433	// legal value that is not a JSON object is a structural error in the caller's
434	// code saying "<what> must be a JSON object", never a parse failure and never
435	// a guessed field or route position. Config errors additionally name the type
436	// actually received ("got <type>"); the request wording omits it.
437	func requireJSONObject(doc json.RawMessage, code, what string, nameType bool) *Failure {
438		if len(doc) == 0 || doc[0] != '{' {
439			if nameType {
440				return failuref(code, "%s must be a JSON object, got %s", what, jsonTypeName(doc))
441			}
442			return failuref(code, "%s must be a JSON object", what)
443		}
444		return nil
445	}
446	
447	// Request is one resolution request: an HTTP method and a request target
448	// (path with an optional raw query string).
449	type Request struct {
450		Method string `json:"method"`
451		Target string `json:"target"`
452	}
453	
454	// Resolution is the successful result of matching a request.
455	type Resolution struct {
456		RouteID     string `json:"routeId"`
457		UpstreamURL string `json:"upstreamURL"`
458	}
459	
460	// Failure carries a stable machine-readable code and a human-readable reason.
461	type Failure struct {
462		Code       string   `json:"code"`
463		Reason     string   `json:"reason"`
464		Candidates []string `json:"candidates,omitempty"`
465	}
466	
467	func (f *Failure) Error() string { return f.Code + ": " + f.Reason }
468	
469	func failuref(code, format string, args ...any) *Failure {
470		return &Failure{Code: code, Reason: fmt.Sprintf(format, args...)}
471	}
472	
473	// ParseConfig parses and fully validates the route configuration.
474	func ParseConfig(data []byte) (*Config, *Failure) {
475		var cfg Config
476		if err := json.Unmarshal(data, &cfg); err != nil {
477			if f, ok := err.(*Failure); ok {
478				return nil, f
479			}
480			return nil, failuref("invalid_config", "config is not valid JSON: %v", err)
481		}
482		if f := cfg.validate(); f != nil {
483			return nil, f
484		}
485		return &cfg, nil
486	}
487	
488	func (cfg *Config) validate() *Failure {
489		seenIDs := make(map[string]int, len(cfg.Routes))
490		for i := range cfg.Routes {
491			route := &cfg.Routes[i]
492			loc := fmt.Sprintf("route %d", i+1)
493			if route.ID == "" {
494				return failuref("invalid_config", "%s: id must be non-empty", loc)
495			}
496			if first, ok := seenIDs[route.ID]; ok {
497				return failuref("invalid_config", "%s: duplicate id %q (already used by route %d)", loc, route.ID, first)
498			}
499			seenIDs[route.ID] = i + 1
500	
501			if len(route.Methods) == 0 {
502				return failuref("invalid_config", "%s (id %q): methods must be a non-empty array", loc, route.ID)
503			}
504			for _, method := range route.Methods {
505				switch {
506				case method == "":
507					return failuref("invalid_config", "%s (id %q): methods must not contain empty entries", loc, route.ID)
508				case method == "*":
509					// Wildcard matching any legal method.
510				case !isToken(method):
511					return failuref("invalid_config", "%s (id %q): invalid method %q", loc, route.ID, method)
512				}
513			}
514	
515			if f := validatePrefix(route.PathPrefix, loc, route.ID); f != nil {
516				return f
517			}
518			if f := validateUpstream(route.Upstream, loc, route.ID); f != nil {
519				return f
520			}
521		}
522		return nil
523	}
524	
525	func validatePrefix(prefix, loc, id string) *Failure {
526		switch {
527		case prefix == "" || prefix[0] != '/':
528			return failuref("invalid_config", "%s (id %q): pathPrefix must start with /", loc, id)
529		case prefix != "/" && strings.HasSuffix(prefix, "/"):
530			return failuref("invalid_config", "%s (id %q): pathPrefix must not end with / except for root", loc, id)
531		case strings.ContainsAny(prefix, "?#"):
532			return failuref("invalid_config", "%s (id %q): pathPrefix must not contain a query string or fragment", loc, id)
533		case !validPercentEscapes(prefix):
534			return failuref("invalid_config", "%s (id %q): pathPrefix contains an invalid percent escape", loc, id)
535		}
536		return nil
537	}
538	
539	// upstreamParts is the one shared reading of a raw upstream URL's address
540	// boundaries. Every field is a slice of the original bytes (nothing is
541	// copied, decoded or normalized), so validation and joining cannot disagree
542	// about where one part ends and the next begins:
543	//
544	//	scheme "://" [userinfo "@"] hostPort basePath
545	//
546	// authority runs from after "://" to the first path slash, and hostPort is
547	// the authority after its last '@', so colons in userinfo or the base path
548	// can never be read as part of an IPv6 host, while brackets, a port and a
549	// zone stay inside hostPort.
550	type upstreamParts struct {
551		schemeEnd int    // index of the ':' in "://", or -1 when the scheme is absent
552		authority string // bytes between "://" and the first path slash (userinfo included)
553		hostPort  string // authority after the last '@' (host plus optional port)
554		basePath  string // from the first path slash to the end, or ""
555	}
556	
557	// splitUpstream applies the single boundary rule shared by the bracketed-host
558	// check, the unbracketed-IPv6 check and the final join. It never rejects
559	// anything on its own: a raw value without "://" comes back with schemeEnd
560	// set to -1 and empty parts, leaving the generic absolute-URL check to
561	// report it, exactly as the per-caller preamble used to.
562	func splitUpstream(raw string) upstreamParts {
563		p := upstreamParts{schemeEnd: -1}
564		i := strings.Index(raw, "://")
565		if i < 0 {
566			return p
567		}
568		p.schemeEnd = i
569		tail := raw[i+3:]
570		if j := strings.IndexByte(tail, '/'); j >= 0 {
571			p.authority = tail[:j]
572			p.basePath = tail[j:]
573		} else {
574			p.authority = tail
575		}
576		// Any userinfo precedes the host and ends at the last '@'; that boundary
577		// is what keeps a userinfo colon out of the IPv6-host checks.
578		p.hostPort = p.authority
579		if k := strings.LastIndexByte(p.authority, '@'); k >= 0 {
580			p.hostPort = p.authority[k+1:]
581		}
582		return p
583	}
584	
585	func validateUpstream(raw, loc, id string) *Failure {
586		if strings.ContainsAny(raw, "?#") {
587			return failuref("invalid_config", "%s (id %q): upstream must not contain a query string or fragment", loc, id)
588		}
589		// Validate the host's IP-literal spelling against the raw string before
590		// url.Parse: square brackets are the IP-literal marker, so whatever they
591		// enclose must be a legal IPv6 address (full, compressed or IPv4-tail,
592		// zone included) rather than a name or an IPv4 address, and an IPv6
593		// literal may never appear without that pair of brackets. Both checks and
594		// the later join read the same splitUpstream boundaries, which keeps the
595		// rules independent of url.Parse's parser strictness and lets the reason
596		// name the field and the actual problem instead of surfacing a generic URL
597		// parse error (an unbracketed literal otherwise reaches the user as a
598		// misleading "invalid port" complaint).
599		p := splitUpstream(raw)
600		if f := validateBracketedUpstreamHost(p, loc, id); f != nil {
601			return f
602		}
603		if f := validateUnbracketedUpstreamHost(p, loc, id); f != nil {
604			return f
605		}
606		u, err := url.Parse(raw)
607		if err != nil {
608			return failuref("invalid_config", "%s (id %q): upstream is not a valid URL: %v", loc, id, err)
609		}
610		if u.Scheme != "http" && u.Scheme != "https" {
611			return failuref("invalid_config", "%s (id %q): upstream must be an absolute http or https URL", loc, id)
612		}
613		if u.Host == "" {
614			return failuref("invalid_config", "%s (id %q): upstream must include a host", loc, id)
615		}
616		return nil
617	}
618	
619	// validateBracketedUpstreamHost checks the split raw upstream's authority for
620	// an IP literal in square brackets: brackets are reserved for an IPv6 (or
621	// future IP-version) literal, so their content must parse as an IPv6 address
622	// — full form, compressed form or an IPv6 address with an embedded IPv4
623	// tail — and the brackets must wrap the whole host exactly once:
624	//
625	//	"[" IPv6 "]" [ ":" *DIGIT ]
626	//
627	// A port, userinfo and a percent-encoded zone ("%25eth0") are allowed and
628	// never alter the literal's bytes; an empty pair of brackets, a plain
629	// hostname such as "[not-an-ip]", a bare IPv4 address such as
630	// "[127.0.0.1]", a malformed IPv6 literal, a missing closing bracket, a
631	// second bracket group such as "[::1][::2]", a stray closing bracket or any
632	// other text between the closing bracket and the start of the base path
633	// (including junk around the port such as "[::1]:80a" or "[::1]x]:80") are
634	// rejected — a legal first literal never legitimizes trailing content. The
635	// reason names the route, its id and the upstream field. This is a content
636	// error in a syntactically valid JSON document, never a JSON parse failure,
637	// and the rule is enforced here on the raw bytes rather than left to
638	// url.Parse's parser strictness.
639	func validateBracketedUpstreamHost(p upstreamParts, loc, id string) *Failure {
640		if p.schemeEnd < 0 {
641			return nil // no scheme: the generic absolute-URL check reports this
642		}
643		hostPort := p.hostPort
644	
645		if !strings.ContainsAny(hostPort, "[]") {
646			return nil // ordinary reg-name (domain) or bare IPv4 host stays as-is
647		}
648		label := routeLabel(loc, id)
649		if !strings.HasPrefix(hostPort, "[") {
650			return failuref("invalid_config",
651				"%s: upstream bracketed host must be a single '[' IPv6 address ']' pair: '[' may only open the host", label)
652		}
653		closeBracket := strings.IndexByte(hostPort, ']')
654		if closeBracket < 0 {
655			return failuref("invalid_config",
656				"%s: upstream bracketed host must be a valid IPv6 address but the closing ']' is missing", label)
657		}
658		literal := hostPort[1:closeBracket]
659		// The zone delimiter is percent-encoded in the URL ("%25"); decode the
660		// literal's escapes once so netip sees "fe80::1%eth0" while every other
661		// byte keeps its original spelling.
662		decoded, err := url.PathUnescape(literal)
663		if err != nil {
664			return invalidBracketedHost(label, literal)
665		}
666		addr, err := netip.ParseAddr(decoded)
667		if err != nil || !addr.Is6() {
668			// ParseAddr accepts a bare IPv4 address; brackets may only carry
669			// IPv6, so "[127.0.0.1]" is rejected even though it is a valid IP.
670			return invalidBracketedHost(label, literal)
671		}
672		// The one closing bracket ends the host: the rest of the authority may
673		// be empty or the optional port the generic parser already allows
674		// (":" followed by digits, an empty port included). A repeated bracket
675		// group, a stray ']', or any other text before, beside or after a port
676		// fails here even though the first literal was valid — the brackets
677		// must enclose the whole host exactly once.
678		suffix := hostPort[closeBracket+1:]
679		switch {
680		case suffix == "":
681			return nil
682		case strings.ContainsAny(suffix, "[]"):
683			return invalidBracketedHostShape(label, suffix)
684		case suffix[0] != ':':
685			return invalidBracketedHostShape(label, suffix)
686		}
687		port := suffix[1:]
688		for i := 0; i < len(port); i++ {
689			if port[i] < '0' || port[i] > '9' {
690				return invalidBracketedHostShape(label, suffix)
691			}
692		}
693		return nil
694	}
695	
696	// invalidBracketedHost builds the content error for a bracketed host whose
697	// content is not a legal IPv6 literal.
698	func invalidBracketedHost(label, literal string) *Failure {
699		return failuref("invalid_config",
700			"%s: upstream host in brackets must be a valid IPv6 address, but %q is not a legal IPv6 address", label, literal)
701	}
702	
703	// validateUnbracketedUpstreamHost rejects an IPv6 literal written without the
704	// square brackets an IP literal requires in a URL's authority:
705	//
706	//	host = IP-literal / IPv4address / reg-name
707	//	IP-literal = "[" ( IPv6address / ... ) "]"
708	//
709	// A bare "2001:db8::1" leaves the host/port boundary undefined (the reader
710	// cannot tell "::1" from "::1:8080" with a port), so the literal must be
711	// wrapped as "[2001:db8::1]" rather than guessed at: brackets are never
712	// inserted and a trailing run of digits is never promoted to a port. The
713	// check fires for every IPv6 spelling — the full form, the compressed form
714	// ("::1"), an IPv6 address with an embedded IPv4 tail ("::ffff:192.0.2.1")
715	// and a percent-encoded zone ("%25eth0") — whether or not a ":<digits>"
716	// port is also present and whether userinfo precedes the host.
717	//
718	// Ordinary domains and bare IPv4 hosts (with or without a port) stay
719	// untouched, and the colons in userinfo or the base path are never
720	// inspected: only hostPort — the authority after the last '@' and before
721	// the first '/' according to the shared splitUpstream boundaries — is
722	// considered. Like the bracketed-host rule this is a content error in a
723	// syntactically valid JSON document, never a JSON parse failure, and it is
724	// decided on the raw bytes before url.Parse so the wording cannot regress to
725	// that parser's generic "invalid port" error.
726	func validateUnbracketedUpstreamHost(p upstreamParts, loc, id string) *Failure {
727		if p.schemeEnd < 0 {
728			return nil // no scheme: the generic absolute-URL check reports this
729		}
730		hostPort := p.hostPort
731		if hostPort == "" || strings.ContainsAny(hostPort, "[]") {
732			// No host (the generic check reports it) or a bracketed literal,
733			// which the bracketed-host validator owns.
734			return nil
735		}
736	
737		// A bare IPv6 literal carries at least two colons; a reg-name may contain
738		// a single colon only in the port separator, so skip the parse for those.
739		host := hostPort
740		if strings.Count(host, ":") < 2 {
741			return nil
742		}
743		// A trailing ":<digits>" might be a port; test the address without it as
744		// well, since an unbracketed address with a port ("fe80::1:8080") is
745		// exactly the ambiguous spelling that must be refused rather than parsed
746		// as host plus port. The suffix is only stripped once: a real bare IPv6
747		// literal without a port is tested first and rejected anyway.
748		candidates := []string{host}
749		if i := strings.LastIndexByte(host, ':'); i >= 0 {
750			port := host[i+1:]
751			if port != "" && isDigits(port) {
752				candidates = append(candidates, host[:i])
753			}
754		}
755		for _, cand := range candidates {
756			decoded, err := url.PathUnescape(cand)
757			if err != nil {
758				continue
759			}
760			addr, err := netip.ParseAddr(decoded)
761			if err == nil && addr.Is6() {
762				return failuref("invalid_config",
763					"%s: upstream IPv6 host %q is missing its square brackets: an IPv6 literal must be enclosed in a pair of brackets with any port outside them (e.g. \"[2001:db8::1]:8080\"); brackets are never added and a trailing number is not guessed as a port",
764					routeLabel(loc, id), host)
765			}
766		}
767		return nil
768	}
769	
770	// isDigits reports whether s is a non-empty run of ASCII digits.
771	func isDigits(s string) bool {
772		if s == "" {
773			return false
774		}
775		for i := 0; i < len(s); i++ {
776			if s[i] < '0' || s[i] > '9' {
777				return false
778			}
779		}
780		return true
781	}
782	
783	// invalidBracketedHostShape builds the content error for a bracketed host
784	// whose trailing bytes break the "single '[' IPv6 ']' pair plus optional
785	// port" grammar, e.g. a repeated bracket group, a stray closing bracket or
786	// non-port text after the closing bracket.
787	func invalidBracketedHostShape(label, suffix string) *Failure {
788		return failuref("invalid_config",
789			"%s: upstream bracketed host must be a single '[' IPv6 address ']' pair followed only by an optional port, but %q follows the closing ']'", label, suffix)
790	}
791	
792	// requestJSON mirrors Request but keeps method and target raw, so a valid
793	// JSON document whose fields merely have the wrong JSON type is reported on
794	// the offending field instead of as a generic JSON decode error.
795	type requestJSON struct {
796		Method json.RawMessage `json:"method"`
797		Target json.RawMessage `json:"target"`
798	}
799	
800	// ParseRequest parses and validates one JSON request. Three failure shapes are
801	// kept apart: a document whose JSON syntax is broken fails as a parse failure
802	// without guessing a field; a syntactically valid non-object document (array,
803	// number, string, boolean or null) must be a JSON object; a valid object whose
804	// method or target is not a string fails on that field, naming the JSON type
805	// actually received (null counts as a type error, never as a missing field).
806	// method is always checked before target, regardless of the key order in the
807	// object. Only after both fields are present strings are their contents
808	// (required method, legal token, absolute target without a fragment or a bad
809	// percent escape) validated, so an empty string stays a content error.
810	func ParseRequest(data []byte) (*Request, *Failure) {
811		body, err := unmarshalJSONValue(data)
812		if err != nil {
813			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
814		}
815		if f := requireJSONObject(body, "invalid_request", "request", false); f != nil {
816			return nil, f
817		}
818	
819		var rj requestJSON
820		if err := json.Unmarshal(body, &rj); err != nil {
821			// The document already parsed as one JSON value and starts with '{';
822			// keep this as a parse failure rather than a field error if the object
823			// itself cannot be read.
824			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
825		}
826	
827		var req Request
828		// method is always checked before target, regardless of the key order in
829		// the object; the absent/null/non-string distinction is the shared
830		// decodeStringField, so only the request wording is added here.
831		if f := decodeRequestStringField(rj.Method, "method", &req.Method); f != nil {
832			return nil, f
833		}
834		if f := decodeRequestStringField(rj.Target, "target", &req.Target); f != nil {
835			return nil, f
836		}
837	
838		switch {
839		case req.Method == "":
840			return nil, failuref("invalid_request", "method is required")
841		case !isToken(req.Method):
842			return nil, failuref("invalid_request", "method %q is not a legal HTTP method", req.Method)
843		}
844		switch {
845		case req.Target == "" || req.Target[0] != '/':
846			return nil, failuref("invalid_request", "target must start with /")
847		case strings.Contains(req.Target, "#"):
848			return nil, failuref("invalid_request", "target must not contain a fragment")
849		case !validPercentEscapes(req.Target):
850			return nil, failuref("invalid_request", "target contains an invalid percent escape")
851		}
852		return &req, nil
853	}
854	
855	// decodeRequestStringField renders the request wording for one string field;
856	// the absent/null/non-string decision itself is the shared
857	// decodeStringField. An absent field (no such key) is left as the zero value
858	// so the later content checks keep their "field is required" behavior; null
859	// or any non-string JSON value is a type error that names the field and the
860	// JSON type that was actually supplied.
861	func decodeRequestStringField(raw json.RawMessage, field string, dst *string) *Failure {
862		if !decodeStringField(raw, dst) {
863			return failuref("invalid_request", "%s must be a string, got %s", field, jsonTypeName(raw))
864		}
865		return nil
866	}
867	
868	// jsonTypeName names the JSON type of a syntactically valid raw value, in the
869	// terms the request error reasons use: "null", "a boolean", "a number",
870	// "a string", "an array" or "an object".
871	func jsonTypeName(raw json.RawMessage) string {
872		switch bytes.TrimSpace(raw)[0] {
873		case 'n':
874			return "null"
875		case 't', 'f':
876			return "a boolean"
877		case '"':
878			return "a string"
879		case '[':
880			return "an array"
881		case '{':
882			return "an object"
883		default:
884			return "a number"
885		}
886	}
887	
888	// Resolve matches a validated request against a validated configuration and
889	// computes the upstream URL. Failure codes are route_not_found and
890	// route_conflict.
891	func Resolve(cfg *Config, req *Request) (*Resolution, *Failure) {
892		path := req.Target
893		if i := strings.IndexByte(path, '?'); i >= 0 {
894			path = path[:i]
895		}
896	
897		type candidate struct {
898			route    *Route
899			concrete bool
900		}
901		var matched []candidate
902		for i := range cfg.Routes {
903			route := &cfg.Routes[i]
904			concrete, wildcard := methodMatch(route.Methods, req.Method)
905			if !concrete && !wildcard {
906				continue
907			}
908			if !prefixMatch(route.PathPrefix, path) {
909				continue
910			}
911			matched = append(matched, candidate{route, concrete})
912		}
913		if len(matched) == 0 {
914			return nil, failuref("route_not_found", "no route matches %s %s", req.Method, path)
915		}
916	
917		// Longest prefix wins.
918		bestLen := 0
919		for _, c := range matched {
920			if n := len(c.route.PathPrefix); n > bestLen {
921				bestLen = n
922			}
923		}
924		winners := matched[:0]
925		for _, c := range matched {
926			if len(c.route.PathPrefix) == bestLen {
927				winners = append(winners, c)
928			}
929		}
930	
931		// Among equal prefixes a concrete method beats the wildcard.
932		var concrete []candidate
933		for _, c := range winners {
934			if c.concrete {
935				concrete = append(concrete, c)
936			}
937		}
938		if len(concrete) > 0 {
939			winners = concrete
940		}
941		if len(winners) > 1 {
942			ids := make([]string, 0, len(winners))
943			for _, c := range winners {
944				ids = append(ids, c.route.ID)
945			}
946			sort.Strings(ids)
947			f := failuref("route_conflict", "multiple routes match %s %s", req.Method, path)
948			f.Candidates = ids
949			return nil, f
950		}
951	
952		upstreamURL, f := joinUpstream(winners[0].route, path, req.Target)
953		if f != nil {
954			return nil, f
955		}
956		return &Resolution{RouteID: winners[0].route.ID, UpstreamURL: upstreamURL}, nil
957	}
958	
959	// methodMatch reports whether the method list matches the request method
960	// concretely (an exact, case-sensitive entry) or via the "*" wildcard.
961	func methodMatch(methods []string, method string) (concrete, wildcard bool) {
962		for _, m := range methods {
963			switch {
964			case m == "*":
965				wildcard = true
966			case m == method:
967				concrete = true
968			}
969		}
970		return concrete, wildcard
971	}
972	
973	// prefixMatch matches raw encoded paths on segment boundaries: "%2F" is never
974	// treated as a separator and the root prefix matches every origin-path.
975	func prefixMatch(prefix, path string) bool {
976		if prefix == "/" {
977			return true
978		}
979		if path == prefix {
980			return true
981		}
982		return strings.HasPrefix(path, prefix) && path[len(prefix)] == '/'
983	}
984	
985	// joinUpstream strips the route prefix from the request path and joins the
986	// remainder onto the upstream base path with exactly one slash at the
987	// junction. The junction is one run of literal slashes: every trailing
988	// slash on the base path and every leading slash on the remainder are
989	// merged into that single slash, even when either side contributes
990	// several. Nothing else is normalized: slashes inside either part, the
991	// remainder's trailing slashes (once non-slash content has appeared),
992	// ".", ".." and percent escapes such as "%2F" are carried over byte for
993	// byte, never decoded first. The base path is sliced out of the raw
994	// upstream so joining never re-encodes, reorders or drops anything
995	// outside the junction. The raw query is preserved verbatim unless the
996	// route defines queryTransforms, in which case they rewrite it after
997	// route selection.
998	func joinUpstream(route *Route, path, target string) (string, *Failure) {
999		if _, err := url.Parse(route.Upstream); err != nil {
1000			// Config validation already rejected this.
1001			return "", failuref("invalid_config", "route %q has an invalid upstream: %v", route.ID, err)
1002		}
1003	
1004		var remainder string
1005		switch {
1006		case route.PathPrefix == "/":
1007			// Root keeps the whole following path; "/" itself has an empty remainder.
1008			if path != "/" {
1009				remainder = path
1010			}
1011		default:
1012			remainder = path[len(route.PathPrefix):] // "" or "/...", boundary is a literal slash
1013		}
1014	
1015		// Slice the validated upstream raw so nothing outside the junction is
1016		// normalized or re-escaped. The address boundaries come from the same
1017		// splitUpstream reading the host validators used (scheme://authority
1018		// followed by the base path), so joining can never split userinfo, the
1019		// IPv6 brackets, the port or the base path differently than validation.
1020		parts := splitUpstream(route.Upstream)
1021		basePath := parts.basePath
1022	
1023		// Collapse only the junction run: all trailing slashes of the base
1024		// path meet all leading slashes of the remainder, and the junction
1025		// keeps exactly one slash whether or not anything follows them. A
1026		// remainder made entirely of slashes has no content past the run, so
1027		// it likewise ends in that single slash.
1028		baseTrimmed := strings.TrimRight(basePath, "/")
1029		rest := strings.TrimLeft(remainder, "/")
1030		joined := baseTrimmed + "/" + rest
1031	
1032		result := route.Upstream[:parts.schemeEnd+3] + parts.authority + joined
1033		query, f := applyQueryTransforms(route.QueryTransforms, target)
1034		if f != nil {
1035			return "", f
1036		}
1037		return result + query, nil
1038	}
1039	
1040	// isToken reports whether s is an RFC 7230 token, i.e. a legal HTTP method.
1041	func isToken(s string) bool {
1042		if s == "" {
1043			return false
1044		}
1045		for i := 0; i < len(s); i++ {
1046			if !isTokenChar(s[i]) {
1047				return false
1048			}
1049		}
1050		return true
1051	}
1052	
1053	func isTokenChar(c byte) bool {
1054		switch {
1055		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
1056			return true
1057		}
1058		switch c {
1059		case '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~':
1060			return true
1061		}
1062		return false
1063	}
1064	
1065	// validPercentEscapes checks that every "%' is followed by two hex digits.
1066	// Matching and joining stay on raw strings, but malformed escapes are rejected
1067	// up front for both prefixes and request targets.
1068	func validPercentEscapes(s string) bool {
1069		for i := 0; i < len(s); i++ {
1070			if s[i] != '%' {
1071				continue
1072			}
1073			if i+2 >= len(s) || !isHex(s[i+1]) || !isHex(s[i+2]) {
1074				return false
1075			}
1076			i += 2
1077		}
1078		return true
1079	}
1080	
1081	func isHex(c byte) bool {
1082		switch {
