package main

import (
	"encoding/json"
	"fmt"

	cs "github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
)

func resolve(rules, target string) {
	src := `{"routes":[{"id":"r1","methods":["*"],"pathPrefix":"/","upstream":"http://h.internal/base","queryTransforms":` + rules + `}]}`
	cfg, f := cs.ParseConfig([]byte(src))
	if f != nil {
		fmt.Printf("CONFIG FAIL %q: %v\n", target, f)
		return
	}
	req, f := cs.ParseRequest([]byte(`{"method":"GET","target":"` + target + `"}`))
	if f != nil {
		fmt.Printf("REQ FAIL %q: %v\n", target, f)
		return
	}
	res, f := cs.Resolve(cfg, req)
	if f != nil {
		fmt.Printf("RES FAIL %q: %v\n", target, f)
		return
	}
	fmt.Printf("%-70s -> %s\n", target, res.UpstreamURL)
}

func j(s string) string { b, _ := json.Marshal(s); return string(b) }

func main() {
	ab := `[{"op":"rename","name":"a","to":"b"},{"op":"rename","name":"b","to":"c"}]`
	ba := `[{"op":"rename","name":"b","to":"c"},{"op":"rename","name":"a","to":"b"}]`
	resolve(ab, "/p?a=1&b=2&a=3&c=4")
	resolve(ba, "/p?a=1&b=2&a=3&c=4")

	// encoded middle names
	space := `[{"op":"rename","name":"a","to":` + j("mid name") + `},{"op":"rename","name":` + j("mid name") + `,"to":"z"}]`
	resolve(space, "/p?a=1&mid+name=9&mid%20name=8")
	plus := `[{"op":"rename","name":"a","to":` + j("m+n") + `},{"op":"rename","name":` + j("m+n") + `,"to":"z"}]`
	resolve(plus, "/p?a=1&m%2Bn=9")
	// literal plus distinct from space: a -> "m+n", then rule for "m n" (space) must not hit
	plusVsSpace := `[{"op":"rename","name":"a","to":` + j("m+n") + `},{"op":"rename","name":` + j("m n") + `,"to":"z"}]`
	resolve(plusVsSpace, "/p?a=1&m+n=7")
	zh := `[{"op":"rename","name":"a","to":` + j("中间") + `},{"op":"rename","name":` + j("中间") + `,"to":"z"}]`
	resolve(zh, "/p?a=1")
	// %20 and + both decode to space: a -> "s t", second rule matches a preexisting %20-encoded name too
	sp2 := `[{"op":"rename","name":"a","to":` + j("s t") + `},{"op":"rename","name":` + j("s t") + `,"to":"z"}]`
	resolve(sp2, "/p?a=1&s%20t=2&s+t=3")
	// case sensitivity in the chain
	cs1 := `[{"op":"rename","name":"a","to":"B"},{"op":"rename","name":"b","to":"c"}]`
	resolve(cs1, "/p?a=1&b=2")
	// verbatim values survive two renames
	resolve(ab, "/p?a=%2f+%2F+a=b&a&b=&x=1")
	// self-rename in the middle
	self := `[{"op":"rename","name":"a","to":"b"},{"op":"rename","name":"b","to":"b"},{"op":"rename","name":"b","to":"c"}]`
	resolve(self, "/p?a=1&b=2")
	// absent source in the middle
	abs := `[{"op":"rename","name":"a","to":"b"},{"op":"rename","name":"q","to":"z"},{"op":"rename","name":"b","to":"c"}]`
	resolve(abs, "/p?a=1&a+b=2")
	// no query / empty ?
	resolve(ab, "/p")
	resolve(ab, "/p?")
	resolve(ab, "/p?a=1&")
	resolve(ab, "/p?a=1&&x=2")
	// invalid escapes through chain
	resolve(ab, "/p?a=1&bad%zz=2")
	resolve(ab, "/p?bad%zz=2")
	// three-step chain a->b->c->d
	triple := `[{"op":"rename","name":"a","to":"b"},{"op":"rename","name":"b","to":"c"},{"op":"rename","name":"c","to":"d"}]`
	resolve(triple, "/p?a=1&b=2&c=3&d=4")
	// rename to a name that later gets partially matched by a set-like? only rename here
	// empty fragment chain behavior
	resolve(ab, "/p?&&a=1&&")
	// first rule no-hit, second renames originals only
	noHitFirst := `[{"op":"rename","name":"z","to":"a"},{"op":"rename","name":"a","to":"b"}]`
